#!/bin/bash -e
#
# Run this script from a directory containing a package.json to fetch as many
# of its dependencies as possible from LOCKED_NODE_MODULES
#
# Copyright (c) 2015 Silk Labs, Inc.
# All Rights Reserved.
# Confidential and Proprietary - Silk Labs, Inc.

source $(dirname $0)/../../../../tools/gnu.sh
SILK_SDK_GLUE=$(readlink -f $(dirname $0)/../sdk/glue)

LOCKED_NODE_MODULES=$(readlink -f $(dirname $0)/node_modules)

LIST_REMOTE_DEPS=$(dirname $0)/list_remote_deps.js
echo "NODE_ENV=$NODE_ENV"

mkdir -p node_modules/
if [[ ! -f node_modules/.ok ]]; then
  for mod_ver in $($LIST_REMOTE_DEPS -v package.json | sort -u); do
    mod=${mod_ver%%@*}
    if [[ $mod = silk-sdk-glue ]]; then
      # XXX: HACK to glue in silk-sdk and initialize all our in tree modules.
      cp -laR $SILK_SDK_GLUE node_modules/$mod
      # We need to ensure silk-sdk-glue has it's dependant node modules to run
      # but also not write outside of out/ so run it for each copy separately.
      cd node_modules/$mod
      npm install
      cd -
      continue
    fi

    locked_module="$($(dirname $0)/locate.sh $mod_ver || true)"
    if [[ -n $locked_module ]]; then
      cp -al $locked_module/$mod node_modules
      if [[ -d $locked_module/.bin ]]; then
        cp -al $locked_module/.bin node_modules/
      fi

      # Hack to install node-opencv to run opencv unit tests. Remove this when
      # locked_node_modules is refactored to store various OS versions of a given
      # node module
      if [[ $NODE_ENV == development ]] && [[ $mod = opencv ]]; then
        # Opencv needs to be compiled before it can be used
        cd node_modules/$mod
        npm install --production
        cd -
        continue
      fi
    fi

  done
  touch node_modules/.ok
fi
